"use client";

import { useCallback } from "react";
import { ReactFlow, MiniMap, Controls, Background, useNodesState, useEdgesState, addEdge, BackgroundVariant } from "@xyflow/react";
import "@xyflow/react/dist/style.css";

const initialNodes = [
  { id: '1', position: { x: 250, y: 0 }, data: { label: 'Revenue ↓ 8.2%' }, style: { backgroundColor: 'var(--card)', color: 'var(--foreground)', border: '1px solid var(--border)', borderRadius: '8px', padding: '10px' } },
  { id: '2', position: { x: 250, y: 100 }, data: { label: 'Premium Sales ↓ 19%' }, style: { backgroundColor: 'var(--card)', color: 'var(--foreground)', border: '1px solid var(--border)', borderRadius: '8px', padding: '10px' } },
  { id: '3', position: { x: 250, y: 200 }, data: { label: 'Delivery SLA ↑ 27%' }, style: { backgroundColor: 'var(--card)', color: 'var(--foreground)', border: '1px solid var(--border)', borderRadius: '8px', padding: '10px' } },
  { id: '4', position: { x: 100, y: 300 }, data: { label: 'Complaints ↑ 34%' }, style: { backgroundColor: 'var(--card)', color: 'var(--foreground)', border: '1px solid var(--border)', borderRadius: '8px', padding: '10px' } },
  { id: '5', position: { x: 400, y: 300 }, data: { label: 'Satisfaction Unchanged' }, style: { backgroundColor: 'var(--card)', color: 'var(--foreground)', border: '1px solid var(--destructive)', borderRadius: '8px', padding: '10px' } },
  { id: '6', position: { x: 250, y: 400 }, data: { label: 'Hypothesis: Delivery Reliability' }, style: { backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)', border: 'none', borderRadius: '8px', padding: '10px', fontWeight: 'bold' } },
];

const initialEdges = [
  { id: 'e1-2', source: '1', target: '2', animated: true, style: { stroke: 'var(--muted-foreground)' } },
  { id: 'e2-3', source: '2', target: '3', animated: true, style: { stroke: 'var(--muted-foreground)' } },
  { id: 'e3-4', source: '3', target: '4', style: { stroke: 'var(--success)' }, label: 'Supports' },
  { id: 'e3-5', source: '3', target: '5', style: { stroke: 'var(--destructive)', strokeDasharray: '5,5' }, label: 'Contradicts' },
  { id: 'e4-6', source: '4', target: '6', style: { stroke: 'var(--success)' } },
  { id: 'e5-6', source: '5', target: '6', style: { stroke: 'var(--destructive)', strokeDasharray: '5,5' } },
];

export function EvidenceGraph() {
  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  const onConnect = useCallback(
    (params: any) => setEdges((eds) => addEdge(params, eds)),
    [setEdges]
  );

  return (
    <div style={{ width: '100%', height: '400px' }} className="rounded-xl overflow-hidden border border-border bg-card/50">
      <ReactFlow
        nodes={nodes}
        edges={edges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onConnect={onConnect}
        fitView
      >
        <Controls />
        <MiniMap nodeStrokeColor={() => 'var(--primary)'} nodeColor={() => 'var(--card)'} maskColor="rgba(0,0,0,0.2)" />
        <Background variant={BackgroundVariant.Dots} gap={12} size={1} color="var(--border)" />
      </ReactFlow>
    </div>
  );
}
